   "lead": "Il mondo si trova alla vigilia di un nuovo fenomeno definito \"shock cinese 3.0\", che sarà trainato dalle esportazioni nel campo dell'intelligenza artificiale, delle biotecnologie e della robotica. Secondo Alicia Garcia-Herrero, economista capo per l'Asia-Pacifico di Natixis e ricercatrice del centro studi Bruegel, questa ondata potrebbe rivelarsi ancora più dirompente della precedente. Lo riferisce South China Morning Post – Cina.",
