   "id": "z1f321906",
   "sez": "cultura",
   "titolo": "Dall'artigianato popolare a icona \"Kawaii\": i quattro secoli dell'Akabeko",
   "orig": "From Folk Craft to “Kawaii” Star: Four Centuries of the Akabeko",
   "lead": "Nella regione di Aizu, situata nella prefettura di Fukushima, l’Akabeko rappresenta da quattro secoli uno dei simboli artigianali più amati del folklore giapponese. Questa piccola mucca rossa di cartapesta, caratterizzata dalla testa oscillante, si è evoluta da giocattolo tradizionale a vera e propria icona della cultura \"kawaii\". Originariamente legata a leggende locali sulla forza e la protezione, l'Akabeko rimane il souvenir più celebre dell'area occidentale della prefettura, testimoniando la resilienza e l'identità culturale del popolo nipponico attraverso i secoli. Lo riferisce Nippon.com.",
   "more": [
    "L'Akabeko è un manufatto tradizionale giapponese realizzato in cartapesta laccata. Il nome deriva dall'unione di \"aka\" (rosso) e \"beko\" (mucca nel dialetto locale). Oltre al valore estetico, queste figure sono considerate amuleti per la salute e la fortuna, prodotte ancora oggi seguendo tecniche di lavorazione manuale che risalgono al periodo Edo."
   ],
