   "id": "zd4774c6b",
   "sez": "ingegneria",
   "titolo": "Basamenti in plastica riciclata per il design a Casa Ortega",
   "orig": "Recycled-plastic plinths hold furniture at \"secret\" Barragán house in Mexico City",
   "lead": "In occasione della Design Week Mexico 2026, lo studio di progettazione 2x1 ha allestito un'esposizione nei giardini di Casa Ortega, a Città del Messico. La mostra, intitolata Creative Immersions France-Mexico 2026, ha presentato opere di oltre trenta designer francesi e messicani. Per sostenere i mobili e gli oggetti di design, sono stati utilizzati speciali basamenti realizzati in plastica riciclata. L'evento ha offerto l'opportunità di visitare una residenza privata raramente aperta al pubblico, progettata dal celebre architetto locale Luis Barragán negli anni Quaranta. Lo riferisce Dezeen.",
   "more": [
    "Luis Barragán è stato uno dei più influenti architetti del Novecento, noto per il suo uso magistrale del colore, della luce e dei giardini integrati negli spazi abitativi. Casa Ortega rappresenta uno dei suoi primi capolavori, dove l'ingegneria dei materiali e l'architettura del paesaggio si fondono per creare ambienti intimi e protetti dal caos urbano."
   ],
