   "id": "z20cd5dba",
   "sez": "cucina",
   "titolo": "Spezzatino con le patate: ricetta e consigli per farlo squisito",
   "orig": "Spezzatino con le patate: ricetta e consigli per farlo squisito",
   "lead": "Lo spezzatino con le patate è un classico piatto di carne in umido che può essere preparato utilizzando manzo, vitello o maiale a seconda dei gusti. La ricetta prevede due varianti principali: una versione \"in bianco\" e una arricchita con l'aggiunta di pomodoro, considerata particolarmente saporita. Per ottenere un risultato eccellente, è fondamentale seguire alcuni accorgimenti tecnici durante la cottura lenta, che garantiscono la morbidezza della carne e la giusta consistenza delle patate. Lo riferisce La Cucina Italiana.",
   "more": [
    "Lo spezzatino è una tecnica di cottura in umido tipica della tradizione culinaria familiare, che consiste nel cuocere pezzi di carne di piccolo taglio in un liquido saporito. L'aggiunta delle patate non solo arricchisce il piatto, ma aiuta a creare una salsa densa grazie all'amido rilasciato dai tuberi durante la preparazione."
   ],
