   "id": "z8ab63dc0",
   "sez": "italia",
   "titolo": "Proteste a Roma per il rumore della Metro B e Roma-Lido",
   "orig": "Metro B e Roma-Lido, rivolta contro il rumore: «Servono le barriere»",
   "lead": "I residenti del quadrante romano compreso tra via Lero, viale Egeo e via del Dodecaneso hanno avviato una protesta contro l'eccessivo rumore causato dai passaggi della linea Metro B e della ferrovia Roma-Lido. I cittadini che abitano nell'area situata tra il Tevere e i quartieri limitrofi lamentano un impatto acustico insostenibile e richiedono con urgenza l'installazione di barriere antirumore per tutelare la qualità della vita nelle abitazioni vicine ai binari. La mobilitazione mira a sollecitare un intervento strutturale da parte delle autorità competenti. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "L'inquinamento acustico derivante dai trasporti ferroviari urbani è una problematica comune nelle grandi metropoli. Le barriere antirumore sono pannelli fonoassorbenti o fonoisolanti installati lungo i binari per ridurre la propagazione delle onde sonore verso le aree residenziali, migliorando sensibilmente il comfort ambientale dei cittadini."
   ],
