   "sez": "sport",
   "titolo": "Nuovi campi da calcio FIFA in Sierra Leone e Botswana",
   "orig": "SLFA Begins Groundwork for New FIFA Mini-Pitch at Bo School",
   "lead": "La Sierra Leone Football Association (SLFA) ha avviato i lavori preliminari per la costruzione di un nuovo mini-campo da calcio targato FIFA presso la Bo Government Secondary School. Contemporaneamente, in Botswana, è iniziata la realizzazione di un impianto analogo a Molepolole, su un terreno precedentemente degradato situato dietro un centro commerciale. Entrambi i progetti mirano a potenziare le infrastrutture sportive scolastiche e comunitarie, trasformando aree trascurate in spazi moderni per lo sviluppo del calcio giovanile e la socializzazione locale.",
   "more": [
    "Il programma FIFA Forward sostiene le federazioni nazionali nello sviluppo di infrastrutture calcistiche. I mini-pitch sono campi di dimensioni ridotte, spesso in erba sintetica, ideali per le scuole e le comunità urbane dove lo spazio è limitato, permettendo la pratica sportiva in condizioni di sicurezza e con standard tecnici elevati."
   ],
