   "id": "z07095105",
   "sez": "spazio",
   "titolo": "NASA presenta le prossime passeggiate spaziali sulla ISS",
   "orig": "NASA to Host News Conference Previewing US Spacewalks 100, 101",
   "lead": "La NASA terrà una conferenza stampa martedì 20 ottobre presso il Johnson Space Center di Houston per illustrare i dettagli delle imminenti passeggiate spaziali 100 e 101. Gli interventi degli astronauti avranno l'obiettivo di completare l'installazione dei pannelli solari e il potenziamento del sistema energetico della Stazione Spaziale Internazionale (ISS). L'evento sarà trasmesso in diretta streaming su diverse piattaforme ufficiali dell'agenzia, permettendo al pubblico di seguire i preparativi per queste delicate operazioni extraveicolari. Lo riferisce Nasa.",
   "more": [
    "Le passeggiate spaziali, tecnicamente chiamate attività extraveicolari (EVA), sono fondamentali per la manutenzione e l'aggiornamento della ISS. Il potenziamento del sistema elettrico tramite nuovi pannelli solari è necessario per supportare la crescente richiesta energetica dei numerosi esperimenti scientifici e delle apparecchiature di bordo della stazione."
   ],
