   "id": "za9ed43f3",
   "sez": "musica",
   "titolo": "Levante torna con un nuovo progetto discografico",
   "orig": "Levante - Dell’amore il fallimento e altri passi di danza",
   "lead": "La cantautrice siciliana Levante ha annunciato il suo ritorno sulle scene con il progetto intitolato \"Dell’amore il fallimento e altri passi di danza\". L'opera segna un momento di forte slancio artistico per l'artista, caratterizzandosi per una commistione tra sonorità pop ed elementi ritmici marcati. Il lavoro esplora tematiche profonde legate alle relazioni e alla crescita personale, mantenendo lo stile distintivo che ha reso celebre la cantautrice nel panorama musicale italiano contemporaneo. Lo riferisce OndaRock.",
   "more": [
    "Levante è una delle figure più autorevoli del pop d'autore italiano. Nota per la sua capacità di unire testi introspettivi a melodie orecchiabili, ha costruito una carriera solida che spazia dalla musica alla letteratura, affermandosi come un'artista poliedrica capace di influenzare il gusto musicale attuale con uno stile visivo e sonoro ricercato."
   ],
