   "sez": "mondo",
   "titolo": "Cisgiordania: operative le sanzioni del Regno Unito contro gli insediamenti",
   "orig": "New U.K. regulations allowing West Bank sanctions take effect Thursday",
   "lead": "Il Regno Unito ha reso operativo un nuovo e più severo regime di sanzioni globali contro gli insediamenti israeliani nella Cisgiordania occupata. Le misure, entrate in vigore giovedì 15 ottobre 2026, colpiscono i soggetti coinvolti nella costruzione e nel finanziamento delle colonie, espandendo le tutele per i diritti umani. Londra ha inoltre annunciato un futuro divieto commerciale sui beni provenienti dagli insediamenti, che dovrebbe diventare effettivo entro sei o nove mesi. L'iniziativa punta a contrastare l'espansione abitativa illegale secondo il diritto internazionale e le violazioni collegate.",
   "more": [
    "Le sanzioni internazionali contro gli insediamenti mirano a isolare economicamente le attività edilizie nei territori occupati. Tali misure includono spesso il congelamento dei beni di società finanziatrici e restrizioni commerciali, con l'obiettivo di esercitare pressione diplomatica e legale per il rispetto dei confini riconosciuti dalle Nazioni Unite."
   ],
