   "titolo": "NBA: Kasparas Jakučionis critico dopo l'esordio con i Bucks",
   "orig": "„Bucks“ trenerio pagyrų sulaukęs Jakučionis sau nuolaidų nedarė: turiu būti protingesnis",
   "lead": "Il giovane cestista lituano Kasparas Jakučionis ha mostrato un atteggiamento autocritico dopo la sua solida prestazione nelle partite pre-stagionali NBA con i Milwaukee Bucks. Nonostante gli elogi ricevuti dal suo allenatore, Jakučionis ha dichiarato di dover essere \"più intelligente\" sul campo, ammettendo che i falli precoci hanno compromesso il suo ritmo di gioco. Il difensore ha sottolineato di non voler rinunciare alla propria aggressività, ma ha evidenziato come l'intera squadra debba ancora migliorare notevolmente per raggiungere il livello di gioco desiderato per la stagione regolare. Lo riferisce LRT.",
   "more": [
    "La pre-stagione NBA è un periodo fondamentale per i nuovi giocatori e le reclute internazionali per adattarsi al ritmo e alle regole del basket professionistico americano. È un momento di test in cui le squadre valutano le rotazioni e gli atleti cercano di guadagnarsi un posto stabile nel roster definitivo prima dell'inizio del campionato."
   ],
