   "sez": "tech",
   "titolo": "I cartelli usano droni per mappare i confini e monitorare gli agenti",
   "orig": "Cartels use drones to scout border agents and map smuggling routes, expert warns",
   "lead": "I cartelli della droga stanno intensificando l'uso di droni lungo il confine tra Messico e Stati Uniti per monitorare i movimenti degli agenti di frontiera e mappare nuove rotte per il contrabbando. Secondo esperti di sicurezza, i militari statunitensi hanno rilevato 378 incursioni di droni legati ai cartelli in soli 30 giorni. Gli specialisti avvertono che queste organizzazioni criminali continuano a innovare tecnologicamente, utilizzando velivoli a pilotaggio remoto sempre più sofisticati per eludere la sorveglianza e facilitare le loro attività illecite sul territorio. Lo riferisce Fox News.",
   "more": [
    "L'impiego di droni commerciali modificati per scopi criminali rappresenta una sfida tecnologica crescente per le forze dell'ordine. Questi dispositivi sono difficili da intercettare a causa delle loro dimensioni ridotte e della capacità di volare a basse quote, permettendo ai cartelli di disporre di una propria intelligence aerea a costi contenuti."
   ],
