   "id": "z65a32c63",
   "sez": "ingegneria",
   "titolo": "TUPI: la lampada in rovere che ricorda un uccello a riposo",
   "orig": "crafted from dual-tone solid oak, TUPI lamp by estudio gris resembles bird at rest",
   "lead": "Lo studio gris di Medellín ha presentato la lampada da tavolo TUPI, un oggetto di design realizzato in rovere massiccio bicolore. La struttura della lampada, tornita a mano, è stata progettata per somigliare alla silhouette di un uccello in posizione di riposo. Il becco in legno scuro non è solo un elemento estetico, ma svolge la funzione tecnica di nascondere la sorgente luminosa, permettendo alla lampada di proiettare una luce calda e soffusa verso il basso. Il progetto unisce artigianato tradizionale e soluzioni formali innovative nel campo dell'illuminazione. Lo riferisce Designboom.",
   "more": [
    "Il design di prodotto spesso trae ispirazione da forme organiche e naturali, un approccio noto come biomorfismo. L'uso del legno massiccio e della tornitura manuale valorizza la materia prima, creando oggetti che non sono solo funzionali, ma che stabiliscono un legame tattile ed emotivo con l'utente all'interno dello spazio domestico."
   ],
