   "orig": "The Social Security COLA for 2027 is set. Here's what experts say you need to know",
   "lead": "L'aumento della previdenza sociale basato sull'inflazione per il 2027 è stato ufficialmente stabilito. Gli esperti spiegano che quest'anno l'incremento sarà del 3,6%, traducendosi in poco più di 900 dollari in più il prossimo anno per i beneficiari negli Stati Uniti d'America. Lo riferisce PBS NewsHour.",
