   "lead": "Una start-up cinese ha presentato un prototipo di sistema a sorgente luminosa ultravioletta estrema (EUV), componente considerato il cuore dei sistemi di litografia avanzata, segnando un passo fondamentale nella spinta di Pechino verso l'autosufficienza nelle attrezzature per la produzione di chip. La novità è stata esposta da Langdao Silex alla Fiera internazionale dell'industria cinese a Shanghai, con il novanta per cento dei componenti localizzati. Lo riferisce South China Morning Post – Tecnologia.",
