     "t": "Riporta le accuse anonime di molestie sessuali contro il cantante Geordie Greep, citando la testimonianza della presunta vittima «Laura» raccolta da Paste e la conferma del tastierista Cameron Campbell, che ha lasciato la band. Pubblica anche la risposta di Greep, che si scusa parlando di un \"bacio\" dato credendo erroneamente in un interesse reciproco.",
