     "n": "Al Jazeera",
     "c": "Doha",
     "p": "QA",
     "t": "Inserisce l'apertura del CACCO in un contesto regionale, elencando Perù, Colombia e Brasile come paesi che seguono il modello Bukele. Cita le cifre di omicidi (905, 876, 873) e critiche di gruppi per i diritti umani su CECOT.",
