     "t": "Testo agenziale (Reuters) che aggiunge dettagli assenti altrove: lo scontro tra governo e potere giudiziario su condanne e tagli di budget, e l'annuncio di una visita di Fernández in El Salvador venerdì. Cita gruppi per i diritti che denunciano 'detenzioni arbitrarie' nel modello salvadoregno.",
     "b": "a"
