     "t": "Ricostruisce in dettaglio l'incidente del ragazzo 14enne, con video verificato, e descrive l'ordinanza del governatore Davut Gul: scuole chiuse, divieto di moto, 8.000 operatori mobilitati. Cita cifre di Daily Sabah: 1.277 alluvioni, 15 frane, 194mm di pioggia a Beykoz.",
