     "t": "Analizza se la preparazione sanitaria del Kenya regga anche fuori da Nairobi, citando il caso sospetto (poi negativo) a Wajir e cifre ufficiali su screening, contatti e formazione del personale. Cita il Ministero della Salute, l'OMS e la Croce Rossa keniota, usando toni interrogativi come «non stabilisce» la reale capacità locale.",
